trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; restore; exit 1; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}" apps/web/src/features/docs/entities/procedureMap.generated.json
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(contenu, membres): brouillons réservés aux administrateurs, avatar posé par son seul titulaire, cloche collaborative

- Brouillons : la route publique ne sert plus que les fichiers d'un contenu PUBLIÉ
  (isPubliclyPlaced : date passée, discipline publiée pour un cours, interrupteur pour une page
  éditoriale, galerie publique) ; les fichiers d'un brouillon étaient servis à qui avait l'URL.
  Un administrateur voit la page d'un brouillon (discipline, stage, événement, cours) avec le badge
  « Page non publiée », fichiers par la route privée (PageRenderer audience) ; les aperçus du
  tableau de bord aussi. Clés des pages éditoriales dans le contrat (EDITORIAL_PAGE_KEYS).
- Avatars : un contenu ne montre que l'avatar de son auteur, administrateurs compris
  (assertOwnAvatars dans chaque enregistrement de contenu) ; le sélecteur ne propose que le sien.
- Documents des membres : la cloche collaborative comptait des dépôts hérités (groupe parent,
  administrateurs) qu'on ne pouvait ni ouvrir ni marquer lus — memberDocumentReadableBy pour la
  liste, le marquage et la livraison ; la cloche ouvre le document (/documents?doc=).
- Groupes : Administrateurs reste la racine (pas de parent) ; « sans parent » = sous Administrateurs.
- Avatar : erreurs d'envoi en BAD_REQUEST avec leur message (étaient des erreurs internes).

